                          <tr key={idx} className="hover:bg-gray-50/50">
                            <td className="py-4 px-6 text-gray-900 font-medium">{sig.date}</td>
                            <td className="py-4 px-6 text-gray-600">{sig.day}</td>
                            <td className="py-4 px-6 font-bold text-gray-900">{sig.expected} diners</td>
                            <td className="py-4 px-6">
                              <span className={`px-3 py-1 rounded-full text-xs font-bold ${sig.context === 'Event' ? 'bg-gray-100 text-gray-800' : 'bg-gray-50 text-gray-500'}`}>
                                {sig.context}
                              </span>
                            </td>
                            <td className="py-4 px-6 text-gray-600">{sig.meal}</td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'demand' && (
            <div className="space-y-6">
              <div className="flex justify-between items-start">
                <div>
                  <h1 className="text-3xl lg:text-4xl font-extrabold tracking-tight text-gray-900 mb-2">Demand, made explainable.</h1>
                  <p className="text-gray-500 text-sm">Turn attendance and weather signals into a preparation decision your team can act on.</p>
                </div>
                <button onClick={handleSyncWeather} className="px-4 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 rounded-xl text-xs font-bold text-gray-800 shadow-sm flex items-center gap-2 shrink-0">
                  <span>🔄</span> Sync live weather
                </button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
                  <div className="flex justify-between items-center mb-6">
                    <div>
                      <h3 className="text-base font-bold text-gray-900">Build a forecast</h3>
                      <p className="text-xs text-gray-400">Local model + GPT-5.4 planning note</p>
                    </div>
                    <span className="px-3 py-1 bg-emerald-50 text-[#1A7B48] text-xs font-bold rounded-full flex items-center gap-1">✨ Explainable</span>
                  </div>

                  <form onSubmit={handleCalculateForecast} className="space-y-5">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Expected attendance</label>
                        <input type="number" value={forecastData.expectedAttendance} onChange={e => setForecastData({...forecastData, expectedAttendance: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Day</label>
                        <select value={forecastData.day} onChange={e => setForecastData({...forecastData, day: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                          <option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option>
                        </select>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Meal type</label>
                        <select value={forecastData.mealType} onChange={e => setForecastData({...forecastData, mealType: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                          <option>Lunch</option><option>Dinner</option><option>Breakfast</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Safety buffer · meals</label>
                        <input type="number" value={forecastData.safetyBuffer} onChange={e => setForecastData({...forecastData, safetyBuffer: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Temperature · °C</label>
                        <input type="number" value={forecastData.temperature} onChange={e => setForecastData({...forecastData, temperature: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1">Rainfall · mm</label>
                        <input type="number" value={forecastData.rainfall} onChange={e => setForecastData({...forecastData, rainfall: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" />
                      </div>
                    </div>

                    <button type="submit" className="w-full sm:w-auto px-6 py-3.5 bg-[#142A1E] hover:bg-[#1E3B2C] text-white font-bold rounded-xl text-sm mt-4 flex items-center justify-center gap-2">
                      <span>⚡</span> Calculate preparation plan
                    </button>
                  </form>
                </div>

                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col justify-between">
                  <div>
                    <p className="text-[10px] font-bold tracking-widest text-[#1A7B48] uppercase mb-1">LIVE CONTEXT</p>
                    <h3 className="text-base font-bold text-gray-900 mb-2">Weather at campus</h3>
                    <p className="text-xs text-gray-500 mb-6">Automatically synced on entry via Open-Meteo API.</p>

                    <div className="flex items-center gap-3 mb-6">
                      <span className="text-4xl">☀️</span>
                      <div>
                        <p className="text-3xl font-extrabold text-gray-900">{forecastData.weatherContext?.temp || forecastData.temperature}°</p>
                        <p className="text-xs text-gray-500">{forecastData.weatherContext?.condition || 'Live sync active'}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-100">
                      <div>
                        <span className="text-[11px] font-semibold text-gray-400 block mb-1">Rainfall</span>
                        <p className="text-base font-bold text-gray-900">{forecastData.weatherContext?.rainfall || `${forecastData.rainfall} mm`}</p>
                      </div>
                      <div>
                        <span className="text-[11px] font-semibold text-gray-400 block mb-1">Humidity</span>
                        <p className="text-base font-bold text-gray-900">{forecastData.weatherContext?.humidity || '62%'}</p>
                      </div>
                    </div>
                  </div>
                  <p className="text-[10px] text-gray-400 uppercase tracking-wider mt-6">SOURCE · Open-Meteo API</p>
                </div>
              </div>

              {calculatedPlan && (
                <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-200 mt-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <p className="text-[10px] font-bold tracking-widest text-[#1A7B48] uppercase mb-1">RECOMMENDATION READY</p>
                      <h3 className="text-2xl font-extrabold text-gray-900">Tomorrow’s preparation plan</h3>
                    </div>
                    <span className="px-3 py-1 bg-emerald-50 text-[#1A7B48] text-xs font-bold rounded-full">✓ Saved</span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Predicted demand</span>
                      <p className="text-3xl font-extrabold text-gray-900">{calculatedPlan.predictedDemand}</p>
                    </div>
                    <div className="bg-[#F2F8EE] p-5 rounded-2xl border border-[#D5EAD0]">
                      <span className="text-xs font-semibold text-[#1A7B48] block mb-2">Recommended preparation</span>
                      <p className="text-3xl font-extrabold text-[#1A7B48]">{calculatedPlan.recommendedPrep}</p>
                    </div>
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Planning model</span>
                      <p className="text-xl font-bold text-gray-900">Local + AI</p>
                    </div>
                    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
                      <span className="text-xs font-semibold text-gray-500 block mb-2">Weather input</span>
                      <p className="text-xl font-bold text-gray-900">{calculatedPlan.temperature}°C</p>
                    </div>
                  </div>

                  <div className="p-4 bg-[#F8FBF6] rounded-xl border-l-4 border-[#1A7B48] flex items-start gap-3">
                    <span className="text-base text-[#1A7B48]">✨</span>
                    <div>
                      <span className="text-xs font-bold text-gray-900">AI planning note: </span>
                      <span className="text-xs text-gray-700">{calculatedPlan.planningNote}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab !== 'overview' && activeTab !== 'demand' && activeTab !== 'meals' && (
            <div className="bg-white p-12 rounded-2xl shadow-sm border border-gray-100 text-center">
              <h2 className="text-2xl font-bold text-gray-800 capitalize mb-2">{activeTab.replace('-', ' ')}</h2>
              <p className="text-gray-500 text-sm">Module is active and ready.</p>
            </div>
          )}
        </main>
      </div>

      {showAddMealModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-xl">
            <h3 className="text-xl font-extrabold text-gray-900 mb-2">Add new meal</h3>
            <p className="text-xs text-gray-500 mb-6">Enter details for the upcoming menu item.</p>

            <form onSubmit={handleAddMealSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Meal Name</label>
                <input type="text" value={newMealForm.name} onChange={e => setNewMealForm({...newMealForm, name: e.target.value})} placeholder="e.g. Paneer pulao" className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Category</label>
                <select value={newMealForm.category} onChange={e => setNewMealForm({...newMealForm, category: e.target.value})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                  <option>Lunch</option><option>Dinner</option><option>Breakfast</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Service schedule</label>
                <input type="text" value={newMealForm.service} onChange={e => setNewMealForm({...newMealForm, service: e.target.value})} placeholder="Tomorrow · 20 Mar" className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Planned portions</label>
                <input type="number" value={newMealForm.planned} onChange={e => setNewMealForm({...newMealForm, planned: Number(e.target.value)})} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowAddMealModal(false)} className="flex-1 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl text-sm">Cancel</button>
                <button type="submit" className="flex-1 py-3 bg-[#1A7B48] hover:bg-[#146039] text-white font-bold rounded-xl text-sm">Add meal</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
